package main

import (
	"context"
	"fmt"
	"io"
	"os"

	"github.com/SemRels/publisher-crates/internal/plugin"
)

const pluginSchemaVersion = 1

func main() {
	os.Exit(run(os.Stdout, os.Stderr, os.Getenv))
}

func run(stdout, stderr io.Writer, getenv func(string) string) int {
	return runWithRunner(stdout, stderr, getenv, plugin.ExecRunner{})
}

func runWithRunner(stdout, stderr io.Writer, getenv func(string) string, runner plugin.Runner) int {
	_, _ = fmt.Fprintf(stderr, "plugin_schema_version=%d\n", pluginSchemaVersion)

	cfg, err := plugin.LoadConfig(getenv)
	if err != nil {
		_, _ = fmt.Fprintln(stderr, "publisher-crates:", err)
		return 1
	}

	if cfg.DryRun {
		if cfg.Token == "" {
			_, _ = fmt.Fprintln(stderr, "[dry-run] publisher-crates: would need CARGO_REGISTRY_TOKEN (or SEMREL_PLUGIN_CARGO_REGISTRY_TOKEN) to publish")
		}
		invocations := plugin.BuildInvocations(cfg)
		for index, inv := range invocations {
			pkg := "crate"
			if index < len(cfg.Packages) && cfg.Packages[index] != "" {
				pkg = cfg.Packages[index]
			}
			_, _ = fmt.Fprintf(stderr, "[dry-run] publisher-crates: would publish %s@%s to crates.io with %s\n", pkg, cfg.Version, inv.String())
			_, _ = fmt.Fprintf(stdout, "publisher-crates: [dry-run] would publish %s@%s to crates.io: %s\n", pkg, cfg.Version, inv.String())
		}
		if len(cfg.Packages) == 0 {
			_, _ = fmt.Fprintln(stdout, "publisher-crates: dry-run validation completed")
			return 0
		}
		_, _ = fmt.Fprintf(stdout, "publisher-crates: dry-run validation completed for %d package(s)\n", len(cfg.Packages))
		return 0
	}

	if err := plugin.Publish(context.Background(), cfg, runner, stdout, stderr); err != nil {
		_, _ = fmt.Fprintln(stderr, "publisher-crates:", err)
		return 1
	}

	if len(cfg.Packages) == 0 {
		_, _ = fmt.Fprintln(stdout, "publisher-crates: published crate")
		return 0
	}

	_, _ = fmt.Fprintf(stdout, "publisher-crates: published %d package(s)\n", len(cfg.Packages))
	return 0
}
